Use the active sheet, read the row labels from B4:B6 and column headers from C3:F3. Build a lookup from the two matching columns to the third value by scanning the data table. Write the matched values into C4:F6 as plain values.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = wb.active.title
vws = vals[sheet_name]
ws = wb[sheet_name]

row_labels = []
for r in range(4, 7):
    v = vws.cell(r, 2).value
    if v is not None:
        row_labels.append(str(v).strip())

col_labels = []
for c in range(3, 7):
    v = vws.cell(3, c).value
    if v is not None:
        col_labels.append(str(v).strip())

def is_number(x):
    if isinstance(x, bool):
        return False
    if isinstance(x, (int, float)):
        return True
    try:
        float(x)
        return True
    except (TypeError, ValueError):
        return False

def build_lookup(start_col):
    lookup = {}
    for r in range(1, vws.max_row + 1):
        a = vws.cell(r, start_col).value
        b = vws.cell(r, start_col + 1).value
        c = vws.cell(r, start_col + 2).value
        if a is None or b is None or c is None:
            continue
        if not is_number(c):
            continue
        lookup[(str(a).strip(), str(b).strip())] = c
    return lookup

def complete(lookup):
    return all((rl, cl) in lookup for rl in row_labels for cl in col_labels)

lookup = {}

# Try the apparent data block first, then any 3-column block.
for start in (9,):
    candidate = build_lookup(start)
    if complete(candidate):
        lookup = candidate
        break

if not lookup:
    for start in range(1, max(1, vws.max_column - 1)):
        candidate = build_lookup(start)
        if complete(candidate):
            lookup = candidate
            break

if not lookup:
    best = {}
    best_count = -1
    for start in range(1, max(1, vws.max_column - 1)):
        candidate = build_lookup(start)
        count = sum(1 for rl in row_labels for cl in col_labels if (rl, cl) in candidate)
        if count > best_count:
            best_count = count
            best = candidate
    lookup = best

filled = []
for r in range(4, 7):
    rl = vws.cell(r, 2).value
    if rl is None:
        continue
    rl = str(rl).strip()
    for c in range(3, 7):
        cl = vws.cell(3, c).value
        if cl is None:
            continue
        cl = str(cl).strip()
        val = lookup.get((rl, cl))
        if val is not None:
            try:
                val = float(val)
            except (TypeError, ValueError):
                pass
        ws.cell(r, c).value = val
        filled.append((r, c, val))

wb.save(OUT)

print("sheet:", sheet_name)
print("lookup size:", len(lookup))
print("filled:", filled)
```

